(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zb-sj-prepa-chir-j1-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zb-sj-prepa-chir-j1-ide\",\n \"titre\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 49,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n   \"sha256\": \"208d6a43bcf5d25965c93f89b74d4dd0edac9de9388ef98aad0fd42a1edb1be4\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J1 (IDE)\",\n     \"slug\": \"prepa-chir-j1-ide\",\n     \"pages\": \"\",\n     \"count\": 49,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie n'existe pas chez la femme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. La hernie crurale (fémorale) « survient le plus souvent chez les femmes de 30 à 60 ans » et la hernie ombilicale de l'adulte s'observe surtout chez la femme. La hernie existe donc chez la femme, même si la hernie inguinale prédomine chez l'homme.\\n\\nSource : Cours de chirurgie traumatique et digestif, Hernies, diapo 205 ; licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Hernie crurale, p. 103\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de l'épaulette est la conséquence de la vacuité de la glène dans la luxation de l'épaule\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. La tête humérale sort de la glène : à l'inspection, le moignon de l'épaule est aplati avec un « coup de hache » externe (signe de l'épaulette) ; à la palpation, la cavité glénoïde est vide. L'épaulette est donc la traduction visible de la vacuité de la glène.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Luxation de l'épaule, III Étude clinique, p. 19\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome de Wolkmann siège sur les membres inférieurs\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le syndrome de Wolkmann est une nécrose ischémique des muscles de l'avant-bras (longs fléchisseurs des doigts), surtout chez l'enfant après une fracture supracondylienne du coude ou de l'avant-bras : il siège au membre supérieur.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Fractures de l'avant-bras, syndrome de Wolkmann, p. 34 ; COURS PATHOLOGIE CHIRURGICALE (L2 2023), Fractures de l'humérus, p. 21\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les fractures pathologiques surviennent à la suite des traumatismes minimes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Une fracture pathologique survient sur un os déjà fragilisé (tumeur, métastase, ostéoporose, infection) : un traumatisme minime, voire un geste banal, suffit à la provoquer. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le volet costal est une fracture étagée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le volet costal est défini par deux traits de fracture sur une même côte qui isolent un fragment intermédiaire mobile : c'est une fracture étagée (double). Son instabilité entraîne la respiration paradoxale.\\n\\nSource : Cours de chirurgie traumatique et digestif, Traumatisme du thorax, diapo 6 ; licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Traumatisme du thorax, p. 10\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de Rovsing positif est la mise en évidence du signe pathognomonique de l'appendicite\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai selon la correction nationale. Le signe de Rovsing (douleur de la fosse iliaque droite déclenchée par la pression de la fosse iliaque gauche) est un signe classique d'appendicite aiguë. Remarque : Le cours cite le signe de Rovsing parmi les signes de l'appendicite, mais ne le qualifie pas de « pathognomonique ».\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Appendicite, Formes cliniques (Guinard, Rovsing, Blumberg), p. 115\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'occlusion haute siège sur l'œsophage\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. L'occlusion intestinale est un arrêt du transit dans un segment intestinal : l'occlusion haute siège sur l'intestin grêle (vomissements précoces), l'occlusion basse sur le côlon. L'œsophage ne fait pas partie de l'intestin.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 125-126 ; Cours de chirurgie traumatique et digestif, diapos 229-230\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La tuméfaction de l'étranglement herniaire est dure, réductible et impulsive à la toux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Dans l'étranglement herniaire, la tuméfaction est dure, tendue, douloureuse (maximum au collet), mais irréductible et non impulsive à la toux. « Réductible et impulsive » décrit la hernie simple, non compliquée.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Hernie étranglée, signes physiques, p. 108\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'adénome de la prostate est une maladie bénigne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L'adénome de la prostate est une tumeur bénigne (hypertrophie) de la prostate du sujet âgé ; il ne donne pas de métastases. Sa gravité vient de ses complications (rétention d'urine), à distinguer du cancer de la prostate.\\n\\nSource : Cours de chirurgie traumatique et digestif, Adénome de la prostate, diapos 290-298\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le mal de Pott est une infection disco-vertébrale due au staphylocoque aureus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le mal de Pott est la tuberculose disco-vertébrale, due au bacille de Koch (BK). Les ostéomyélites vertébrales à staphylocoques sont citées dans le cours comme diagnostic différentiel.\\n\\nSource : Cours de chirurgie traumatique et digestif, Mal de Pott, diapos 169-170\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement de l'appendicite est uniquement chirurgical\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le traitement associe toujours un volet médical (apport hydrique, antalgiques, antibiotiques). Le plastron appendiculaire est d'abord traité médicalement (« refroidissement » : antalgiques, vessie de glace, antibiotiques) avant l'appendicectomie. Remarque : Le Cours de chirurgie traumatique et digestif (diapo 215) écrit que « seule l'intervention chirurgicale d'urgence peut résoudre le problème du patient » : la chirurgie reste le traitement de base, mais elle n'est pas le seul traitement.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Appendicite, IX Traitement (indications), p. 117-118\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe capital de la péritonite est la contracture abdominale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L'examen de l'abdomen révèle une contracture abdominale à la palpation : c'est le signe physique majeur de la péritonite. À l'inverse, dans l'occlusion « il n'y a jamais de contracture ».\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Péritonites, période initiale, p. 130 ; Occlusions, p. 124\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les occlusions fonctionnelles sont le fait du dérèglement du système nerveux intestinal\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le cours définit les occlusions fonctionnelles par le « dérèglement du système nerveux intestinal », sous forme de paralysie ou de spasme, sans obstacle organique.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, 1.2 Occlusions fonctionnelles, p. 122\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La femme n'a pas d'urètre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. La femme a un urètre, court (environ 3 à 4 cm), qui va du col de la vessie au méat urinaire situé dans la vulve. C'est sa brièveté qui favorise les infections urinaires. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les brûlures provoquées par contact sont plus graves que celles faites par rayonnement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le cours décrit les brûlures par contact (solides chauds, liquides, gaz, flammes) et par rayonnement (rayons X, radiations atomiques), puis précise : « quel qu'en soit le type, les brûlures sont généralement graves ». Aucun type n'est plus grave par principe.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), Brûlures, II Étiologie, p. 83\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction sus-pubienne est conditionnée par l'impossibilité d'une pose de sonde vésicale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le drainage vésical en urgence se fait d'abord par sondage urétral ; la ponction sus-pubienne est le recours quand le sondage est impossible (obstacle urétral, rétrécissement, traumatisme de l'urètre).\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Rétention urinaire, 4 Traitement, p. 173-174\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'embarrure est une fracture du crâne caractérisée par l'enfoncement d'un fragment osseux vers l'intérieur de la boîte crânienne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. L'embarrure est une fracture du crâne avec enfoncement d'un fragment osseux vers l'intérieur de la boîte crânienne, qui peut comprimer ou léser le cerveau et nécessite souvent une intervention. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Plus le score de Glasgow est élevé plus l'état du malade est grabataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : c'est l'inverse. Le score de Glasgow va de 3 à 15 ; plus il est bas, plus le traumatisme est grave (3 à 8 : grave ; 9 à 12 : modéré ; 13 à 15 : bénin). Un score élevé traduit un patient conscient.\\n\\nSource : NEUROCHIRURGIE L3, Traumatismes crâniens, diapos 17-23\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": 1\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hématome extradural ou épidural est une collection sanguine développée entre la dure-mère et l'os du crâne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. La dure-mère est l'enveloppe la plus externe du cerveau, collée à la face interne de l'os. L'hématome extradural (épidural) se collecte entre l'os du crâne et la dure-mère ; il se révèle typiquement après un intervalle libre.\\n\\nSource : NEUROCHIRURGIE L3, Traumatismes crâniens, anatomie (enveloppes : dure-mère la plus externe), diapo 12 ; Cours de chirurgie traumatique et digestif, diapo 112\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pied bot équin est une déformation dont la pointe du pied est orienté vers le bas\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. « L'équinisme est, avant tout, la flexion forcée du pied, abaissant la pointe et relevant le talon. » La pointe du pied est donc orientée vers le bas.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), Pieds bots congénitaux, III Pied bot varus équin, p. 81\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez celle qui se rapporte à la notion d'intervalle de temps libre chez le traumatisé crânien\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le temps qui s'écoule entre la survenue de l'accident et la prise en charge du patient\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le temps qui sépare la perte de connaissance initiale et la réapparition des troubles de la conscience\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La durée des troubles de la conscience occasionnée par le traumatisme crânien\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Le temps qui sépare la perte de connaissance initiale et la réapparition des troubles de la conscience\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'intervalle libre est le temps pendant lequel le blessé paraît s'améliorer (après la perte de connaissance initiale) avant que son état ne s'aggrave de nouveau : c'est l'élément essentiel du diagnostic d'hématome extradural. Ce n'est ni le délai de prise en charge, ni la durée des troubles de la conscience.\\n\\nSource : Cours de chirurgie traumatique et digestif, Traumatismes crâniens, diapos 110 et 112\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Identifiez dans les items ci-dessous les signes du syndrome de Wolkmann ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Œdème de la jambe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Douleur intense\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Nausées et vomissements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Pâleur et froideur des doigts\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Hyperthermie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Engourdissement ou picotement des doigts\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Douleur intense ; D. D. Pâleur et froideur des doigts ; F. F. Engourdissement ou picotement des doigts\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Le cours décrit une douleur vive de l'avant-bras ou de la main, la cyanose et l'impotence des doigts (ischémie : doigts pâles et froids), des troubles sensitifs à la main (engourdissement, picotements) et l'abolition du pouls radial. Nausées, vomissements et hyperthermie ne font pas partie du tableau. Remarque : Le cours cite aussi l'œdème parmi les symptômes (sous plâtre, à l'avant-bras) ; l'option « œdème de la jambe » est fausse par sa localisation.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Syndrome de Wolkmann, p. 34-39\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Deux items ne font pas partie des étiologies de l'appendicite aigüe parmi ceux qui sont énumérés en dessous. Lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Infections gastro-intestinales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Hernie discale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Parasitoses intestinales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Corps étrangers\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Fécalome\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Alimentation pauvre en viande\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Hernie discale ; F. F. Alimentation pauvre en viande\",\n       \"answerLetters\": [\n        \"B\",\n        \"F\"\n       ],\n       \"explanation\": \"Causes du cours : stercolithe (fécalome), hyperplasie lymphoïde, corps étrangers, infection bacillaire de la flore intestinale, parasites intestinaux. La hernie discale (pathologie du rachis) et une alimentation pauvre en viande n'en font pas partie. Remarque : Les questions 23 et 27 sont identiques dans le sujet (options dans un ordre différent).\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Appendicite, III Pathogénie, p. 113 ; Cours de chirurgie traumatique et digestif, diapo 211\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La liste ci-dessous est celle des signes fonctionnels de la fracture ; lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Crépitation osseuse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Douleur vive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Déformation du membre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Impotence fonctionnelle\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Mobilité anormale du membre atteint\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Douleur vive ; D. D. Impotence fonctionnelle\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Signes fonctionnels (rapportés par le blessé) : la douleur vive et l'impotence fonctionnelle. Déformation, mobilité anormale et crépitation osseuse sont des signes physiques recherchés à l'examen.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), Généralités sur les fractures, III Signes cliniques, p. 65 ; licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), fractures, signes fonctionnels\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Sur le lieu de l'accident, certains gestes suivants sont proscrits en cas de fracture du fémur ; lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Préparer psychologiquement le blessé à l'intervention\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Immobiliser dans une gouttière le membre atteint\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Chercher à réduire une fracture ouverte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Laisser le blessé couché par terre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Baliser l'emplacement du patient\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Faire des manœuvres ou des mobilisations intempestives\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Chercher à réduire une fracture ouverte ; F. F. Faire des manœuvres ou des mobilisations intempestives\",\n       \"answerLetters\": [\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Le cours prescrit : « pas de manœuvres ou de mobilisations intempestives » et « ne pas chercher à réduire une fracture ouverte ». Immobiliser le membre dans une gouttière est au contraire recommandé ; baliser le lieu protège le blessé.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Intervention infirmière dans les fractures des membres, 9.1 Soins sur les lieux de l'accident, p. 46-47\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments de la surveillance post opératoire ci-dessous, trois (3) relèvent de l'état végétatif du patient. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Perméabilité des tuyaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Fréquence respiratoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Pression artérielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Profondeur du coma\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Niveau de conscience\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Fréquence cardiaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Fréquence respiratoire ; C. C. Pression artérielle ; F. F. Fréquence cardiaque\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Le cours sépare l'état neurologique (niveau de conscience, profondeur du coma) et l'état végétatif : pouls (fréquence cardiaque), tension artérielle, rythme respiratoire. La perméabilité des tuyaux concerne la surveillance des sondes.\\n\\nSource : NEUROCHIRURGIE L3, Traumatismes crâniens, soins postopératoires, diapos 51-52\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les items ci-dessous font partie des étiologies de l'appendicite aigüe exceptés deux ; lesquels ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Infections gastro-intestinales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Alimentation pauvre en viande\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Parasitoses intestinales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Corps étrangers\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Hernie discale\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Fécalome\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Alimentation pauvre en viande ; E. E. Hernie discale\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Même question que la 23 : la hernie discale et l'alimentation pauvre en viande ne sont pas des causes d'appendicite. Corps étrangers, parasitoses, fécalome (stercolithe) et infections digestives le sont. Remarque : Les questions 23 et 27 sont identiques dans le sujet.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Appendicite, III Pathogénie, p. 113 ; Cours de chirurgie traumatique et digestif, diapo 211\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les actions suivantes, indiquez les deux à effectuer en urgence chez un patient qui souffre de rétention urinaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. L'adénomectomie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La cystectomie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La ponction sus-pubienne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le sondage urétral\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. La ponction sus-pubienne ; D. D. Le sondage urétral\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"« Drainage vésical : c'est une urgence », par sondage urétral ou ponction sus-pubienne, avec une asepsie rigoureuse. L'adénomectomie est le traitement de la cause (adénome), à distance ; la cystectomie (ablation de la vessie) n'a pas sa place.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Rétention urinaire, 4 Traitement, p. 173-174 ; Cours de chirurgie traumatique et digestif, diapo 307\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez celle qui correspond au score de Glasgow pendant un traumatisme crânien grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 13 à 15\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 9 à 12\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 3 à 8\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 3 à 8\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Glasgow 3 à 8 = traumatisme crânien grave ; 9 à 12 = modéré ; 13 à 15 = bénin ou léger.\\n\\nSource : NEUROCHIRURGIE L3, Traumatismes crâniens, diapo 23\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez les deux (02) soins préopératoires chez le traumatisé crânien\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le rasage soigneux de la zone d'intervention du cuir chevelu\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le rasage soigneux de la totalité du cuir chevelu\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La mise en place d'une ou deux voies veineuses aux membres supérieurs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le rasage soigneux de toutes les zones de pilosité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. L'embellissement du crâne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Le rasage soigneux de la totalité du cuir chevelu ; C. C. La mise en place d'une ou deux voies veineuses aux membres supérieurs\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cours prévoit, avant l'intervention, « le rasage soigneux de la totalité du cuir chevelu et sa détersion ». La mise en place d'une ou deux voies veineuses aux membres supérieurs permet la réanimation et les transfusions pendant l'opération. Remarque : La voie veineuse est un soin préopératoire général ; le cours de neurochirurgie ne la détaille pas pour ce cas (partie hors cours du projet).\\n\\nSource : NEUROCHIRURGIE L3, Traumatismes crâniens, traitement chirurgical, diapo 48\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, indiquez les deux (02) signes physiques de la rétention urinaire aigüe\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le besoin impérieux d'uriner\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La douleur à la palpation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La masse hypogastrique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. L'impossibilité d'uriner\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. La douleur à la palpation ; C. C. La masse hypogastrique\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Signes physiques du globe vésical : une masse hypogastrique pouvant remonter jusqu'à l'ombilic et une douleur à la palpation augmentant le besoin d'uriner. Le besoin impérieux et l'impossibilité d'uriner sont des signes fonctionnels.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Rétention aiguë d'urines, 1.2.2 Signes physiques, p. 170-171\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'abcès froid est une collection purulente chronique causée par quel germe ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Le streptocoque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Le staphylocoque doré ou blanc\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Le bacille de Koch\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Le gonocoque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Le bacille de Koch\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"« Le germe le plus souvent incriminé est le bacille de Koch (BK), donc d'origine tuberculeuse. » Staphylocoque et streptocoque sont les germes de l'abcès chaud.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), Abcès froid, p. 33\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants indiquez les deux (02) précautions à prendre avant la pose d'une poche de sang\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Faire le test de compatibilité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Bien régler le débit de la transfusion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Alimenter correctement le patient\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Vérifier l'écoulement du sang\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. S'assurer que la malade n'a pas de besoin urgent à satisfaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A. Faire le test de compatibilité ; E. E. S'assurer que la malade n'a pas de besoin urgent à satisfaire\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Avant de poser une poche de sang, on vérifie la compatibilité (contrôle ultime au lit du malade : identité, groupe sanguin du patient et de la poche) et on s'assure que le malade n'a pas de besoin urgent à satisfaire (uriner, par exemple), pour ne pas interrompre la transfusion. Régler le débit et vérifier l'écoulement se font pendant la transfusion. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces propositions, indiquez l'ordre chronologique de préparation d'un champ opératoire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Rasage / Détersion / désinfection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Détersion / rasage/ désinfection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Désinfection / rasage/ Détersion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Détersion / rasage/ désinfection\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours décrit : préparation de la peau (brossage, eau-savon = détersion), puis rasage large, puis désinfection (alcool, Bétadine). Ordre : Détersion / Rasage / Désinfection ; la désinfection vient toujours en dernier.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Fractures, 9.2.2 Soins préopératoires (préparer le champ opératoire), p. 48\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relever parmi ces propositions trois (03) localisations de gravité d'une brûlure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Les parties génitales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. La profondeur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La surface corporelle brûlée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Les extrémités\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Le terrain\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Les plis de flexion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. La profondeur ; D. D. Les extrémités ; E. E. Le terrain\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les extrémités (mains, pieds) sont une localisation de gravité : risque d'amputation des doigts et des orteils.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (3-3 Les brûlures graves ; 4.6 Localisation)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétention aiguë est caractérisée par quoi ? (Choisir la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Impossibilité de vider totalement la vessie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Impossibilité brutale et totale d'émettre des urines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Impossibilité brutale et totale de vider totalement la vessie.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. Impossibilité brutale et totale d'émettre des urines\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"« La rétention aiguë ou complète se traduit par l'impossibilité brutale et totale d'uriner ou d'émettre des urines. » L'impossibilité de vider totalement la vessie définit la rétention chronique (incomplète).\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Rétention urinaire, 1.1 Définition, p. 170\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Nommez cette présentation clinique (1 réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Monoplégie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Paraplégie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Tétraplégie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. Tétraplégie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Paralysie des quatre membres = tétraplégie. La paraplégie touche les deux membres inférieurs, la monoplégie un seul membre.\\n\\nSource : ARTHROLOGIE COMPLET, vocabulaire ; Cours de chirurgie traumatique et digestif, Fractures du rachis, diapo 152\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Identifiez le segment du rachis atteint (1 réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Segment cervical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Segment coxal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Segment lombaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Segment cervical\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours indique que les lésions de la moelle donnent « une tétraplégie pour le rachis cervical » et une paraplégie pour le rachis dorsolombaire. Les quatre membres étant paralysés, le segment atteint est cervical. (« Coxal » n'est pas un segment du rachis.)\\n\\nSource : Cours de chirurgie traumatique et digestif, Fractures du rachis, diapo 152\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Enumérez les lésions possibles ayant entraîné cet état (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Traumatisme crânien\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Traumatisme thoracique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Fractures ou luxations cervicales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Traumatismes médullaires\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Compression médullaire\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Traumatisme du bassin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Fractures ou luxations cervicales ; D. D. Traumatismes médullaires ; E. E. Compression médullaire\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La chute a pu provoquer une fracture ou une luxation cervicale, avec atteinte de la moelle : compression (récupération possible si elle est levée vite) ou traumatisme médullaire (section, contusion). Traumatismes crânien, thoracique ou du bassin ne donnent pas une tétraplégie.\\n\\nSource : Cours de chirurgie traumatique et digestif, Fractures du rachis, III Anatomie pathologique, diapos 149-150\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°1 — L'enfant KONAN Fréjus 15 ANS tombe d'un manguier. On constate qu'il ne peut mouvoir ni les deux membres supérieurs ni les deux membres inférieurs.\",\n       \"text\": \"Dans la conduite du rôle de l'infirmier dans les soins à apporter en vue d'éviter les escarres pour cette présentation ; lequel n'en fait pas partie ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Changement de position toutes les 2 heures\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Réfection de lit dès que souillé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Sonde à demeure\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Toilette générale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Sonde nasogastrique pour l'alimentation\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Utiliser des produits irritants sur la peau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F. Utiliser des produits irritants sur la peau\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"La prévention des escarres repose sur les changements de position, des draps toujours secs et bien tirés (réfection du lit dès qu'il est souillé), des soins d'hygiène et du siège, et la protection de la peau. Utiliser des produits irritants sur la peau favorise au contraire les escarres. Remarque : La sonde nasogastrique et la sonde à demeure ne sont pas, à proprement parler, des mesures anti-escarres (elles servent l'alimentation et l'élimination) ; la correction nationale retient seulement les produits irritants.\\n\\nSource : Cours de chirurgie traumatique et digestif, Fractures du rachis, 8-3 Prévention des escarres, diapo 158\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Relever parmi les paramètres suivants les deux (2) permettant de déterminer l'indice de Baux chez le brûlé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Taille\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Age\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Poids\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Hypertension artérielle\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Sexe\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F. Tension artérielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B. Age ; D. D. Hypertension artérielle\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Le cours fonde le pronostic (indice de Baux) sur l'étendue de la brûlure et l'âge du brûlé.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic, p. 92)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Selon la table de Lund et Browder, quelle est la valeur de la surface corporelle brûlée de M. Kouakou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 22,5%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 23,5%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 33%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 23,5%\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Colonne adulte : tronc antérieur 13 % + une cuisse 9,5 % + organes génitaux externes 1 % = 23,5 %.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (4.2 Table de Lund et Browder, colonne adulte)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Quelle est la valeur de l'indice de Baux (IB) pour M. Kouakou ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 72,5\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 82,5\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 87,5\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 87,5\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Indice de Baux = âge + SCB.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Quel est selon son Indice de Baux, le pronostic vital de M. Kouadio ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. La guérison de M. Kouadio est infiniment probable\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. M. Kouadio a une chance sur deux de guérir\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. La mort est quasi certaine pour M. Kouadio\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. M. Kouadio a une chance sur deux de guérir\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon le cours : somme < 50 → guérison infiniment probable ; entre 50 et 100 → une chance sur deux de guérison ; > 100 → mort quasi certaine. Avec 72,5 (ou 87,5), on est entre 50 et 100. Remarque : Le sujet écrit « M. Kouadio » alors que le cas parle de « Mme Kouakou ».\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Parmi les propositions suivantes, relever le critère de gravité de la brûlure correspondant aux circonstances de survenue de la brûlure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Temps d'exposition\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Destruction complète de la membrane basale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Brûlure des orifices naturels\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A. Temps d'exposition\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les circonstances de survenue regroupent le temps d'exposition (plus il est long, plus la brûlure est profonde), le type de produit et la position de la victime par rapport au foyer. La destruction de la membrane basale relève de la profondeur ; la brûlure des orifices naturels, de la localisation.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (IV Critères de gravité, 4.1 Circonstances de survenue)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Dans la prise en charge d'un brûlé, les premiers secours consistent à quoi ? Choisir les deux (2) bonnes réponses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. Corriger les détresses vitales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. Évaluer la surface corporelle brûlée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. Couvrir la victime avec des draps propres ou stériles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D. Refroidir la victime avec de l'eau à 15°C pendant 15 minutes environ\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E. Administrer une ampoule de ACUPAN en IV\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C. Couvrir la victime avec des draps propres ou stériles ; D. D. Refroidir la victime avec de l'eau à 15°C pendant 15 minutes environ\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Premiers secours : refroidissement par l'eau à 15 °C pendant environ 15 minutes, couvrir la victime de champs stériles ou de draps propres, puis couverture d'isolation thermique. Corriger les détresses vitales et évaluer la SCB relèvent du bilan lésionnel ; l'Acupan IV relève de l'analgésie.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.1 Premiers secours)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Le médecin opte pour une rééquilibration hydroélectrolytique. Quelle quantité de soluté doit-on perfuser à M. Kouakou le premier jour ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 1504 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 4606 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 6110 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C. 6110 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Règle de Baxter : QJ1 = 4 mL × 65 kg × 23,5 = 6 110 mL.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3 Réanimation hydroélectrolytique : J1 = Poids × 4 × SCB)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Combien de flacons de solutés de remplissage de 500 ml utiliserez-vous\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 12 flacons de 500 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 13 flacons de 500 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 14 flacons de 500 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 13 flacons de 500 ml\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"6 110 mL ÷ 500 mL = 12,2 flacons : 12 flacons ne suffisent pas (6 000 mL), il en faut 13.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j1-ide__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ÉTUDE DE CAS N°2 — En service des grands brûlés du CHU de Cocody. Vous recevez Mme Kouakou, 49 ans, 65kg, 1,68m, victime de brûlure au tronc antérieur, à la cuisse gauche et à l'organe génital. Hypertendue connue, sa TA est de 90/50 mmHg.\",\n       \"text\": \"Quel est le débit de la perfusion pour ce remplissage hydro électrolytique ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A. 82 gouttes/minute\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B. 84,86 gouttes/minute\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C. 88,35 gouttes/minute\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B. 84,86 gouttes/minute\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (mL) × 20 gouttes / durée (min). Sur 24 heures (1 440 min) : 6 110 × 20 / 1 440 = 84,86 gouttes/minute. Remarque : Le calcul suppose une perfusion régulière sur 24 h. Le cours (règle d'Evans) indique que la moitié doit passer dans les 8 premières heures, ce qui donnerait un débit plus élevé au début.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3) ; formule du débit : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · J1 Chirurgie IDE\",\n       \"sourceFile\": \"J1_CHIRURGIE_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
